-- 获取有效的热搜词
create temporary view  valid_keywords_${grass_region_without_quote}  as
select  T1.keyword
from    search_algo.shopping_guide_fast_rising_keyword T1
inner join (
    select  keyword
    from    srdi_mart.dwd_sr_data_warehouse_nap_diversity_query_keyword_dls_1d
    where   keep_or_not = 'Y'	-- Y表示人工维护的用于trending的过滤条件
       and  grass_region = ${grass_region}
       and  local_date = ${local_date}
    group by keyword
) T2
on      T1.keyword = T2.keyword
where   T1.grass_region = ${grass_region}
  and   T1.grass_date = ${local_date}
group by 1
;

--sql_divide_splitter--
-- 获取商品和关键词的关联关系,并按数组位置排序
create temporary view  item_keyword_relation_${grass_region_without_quote}  as
select  keyword
        ,pos AS array_position
        ,col AS item_id
from    search_algo.shopping_guide_keyword_items T1
lateral view posexplode(T1.top_imp_items) t AS pos, col
where   T1.grass_region = ${grass_region}
  and   T1.grass_date =${local_date}
;

--sql_divide_splitter--
-- 为每个商品选择选择顺序前5的
create temporary view  item_keywords_${grass_region_without_quote} as
select  item_id
        ,keyword
from    (
    select  T1.keyword
            ,T2.item_id
            ,ROW_NUMBER() OVER (PARTITION BY T2.item_id
            ORDER BY T2.array_position, T1.keyword) AS rn
    from    valid_keywords_${grass_region_without_quote} T1
    join item_keyword_relation_${grass_region_without_quote} T2
    on      T1.keyword = T2.keyword
) T3
where   rn <= 5
;

--sql_divide_splitter--
insert overwrite table ${schema}.ads_sr_data_warehouse_nap_trending_item_query_mapping_1d
partition (grass_region = ${grass_region}, local_date = ${local_date})
select  item_id
        ,COLLECT_SET(keyword) as query_list
from    item_keywords_${grass_region_without_quote}
group by item_id
;
